// Signatures transcribed from solid-js@1.9.14 `types/reactive/signal.d.ts`,
// simplified only where the inference machinery (`EffectFunction`, `NoInfer`,
// the overload pairs carrying a seed value) is irrelevant here. Nothing is
// loosened: every callback parameter keeps a callable type, `untrack` keeps its
// `Accessor<T>` argument, `onCleanup` keeps its identity return, and
// `runWithOwner` keeps its `T | undefined`. A stub that widened any of these
// could manufacture a claim no real project can produce.
export type Accessor<T> = () => T;

export interface Owner {
  owned: unknown;
}

export declare function untrack<T>(fn: Accessor<T>): T;
export declare function createRoot<T>(
  fn: (dispose: () => void) => T,
  detachedOwner?: Owner
): T;
export declare function runWithOwner<T>(o: Owner, fn: () => T): T | undefined;
export declare function createEffect(fn: () => void): void;
export declare function createMemo<T>(fn: () => T): Accessor<T>;
export declare function onCleanup<T extends () => unknown>(fn: T): T;
